def main():
    manifest=json.loads((ROOT/'dataset/task_manifest.json').read_text(encoding='utf-8'))
    selection=json.loads((ROOT/'dataset/extension_selection.json').read_text(encoding='utf-8'))
    by_id={t['task_id']:t for t in manifest}
    created=[]
    reviews=json.loads((ROOT/'dataset/translation_reviews.json').read_text(encoding='utf-8'))
    for task_id in selection['selected_task_ids']:
        task=by_id[task_id]
        for filename in task['source_prompt_files']:
            source=ROOT/'tasks'/task_id/'prompts/en'/filename
            original=source.read_text(encoding='utf-8').removesuffix(CONTRACT)
            if task_id in SUFFIXES: original=original.removesuffix(SUFFIXES[task_id])
            variants={}
            for lang,index in [('hi',0),('hinglish',1)]:
                table=P.get(task_id,{})
                lines=[]
                for line in original.splitlines():
                    # Blank lines and literal schema rows are carried verbatim.
                    lines.append(table.get(line,(line,line))[index])
                body='\n'.join(lines).rstrip('\n')+'\n'
                variants[lang]=body+SUFFIXES.get(task_id,'')+CONTRACT
                out=ROOT/'tasks'/task_id/'prompts'/lang/filename
                out.parent.mkdir(parents=True,exist_ok=True)
                out.write_text(variants[lang],encoding='utf-8',newline='\n')
                created.append(out.relative_to(ROOT).as_posix())
        task['translations']['hi']='AI translated and self-reviewed'
        task['translations']['hinglish']='AI translated and self-reviewed'
        task['validation']['semantic_review']='passed'
        reviews[task_id]={
            'reviewer':'AI self-review','model':'GPT-6 Luna (user-selected chat model)',
            'independent_human_review':False,'review_status':'reviewed_after_natural_language_revision',
            'checked_prompt_files':task['source_prompt_files'],
            'checks':{key:True for key in ('requirements','negations','numbers_and_dates','round_order','no_new_hints','technical_literals','hindi_naturalness','hinglish_naturalness','backtranslation_comparison')},
            'notes':'Compared each Hindi and Roman-script Hinglish instruction turn against the English source and back-checked the meaning. Checked requirements, negation, numeric/date bounds, sequencing, protected literals, output contracts and prohibited actions. Technical paths, schemas, commands, enums, headings and exact strings were preserved. This is AI translation and AI self-review, not independent human validation.',
            'unresolved_issues':[]}
    if len(created)!=30: raise ValueError('Expected exactly 30 new translated prompts')
    from bench.durable import atomic_json
    atomic_json(ROOT/'dataset/translation_reviews.json',reviews)
    atomic_json(ROOT/'dataset/task_manifest.json',manifest)
    return created

if __name__=='__main__':
    files=main();print(json.dumps({'created':len(files),'translation_files':files},ensure_ascii=False,indent=2))
